public class Student
{
    public string Name { get; set; }
    public List<string> Courses { get; set; }
}

List<Student> students = new List<Student>
{
    new Student { Name = "John", Courses = new List<string> { "Math", "Science" } },
    new Student { Name = "Jane", Courses = new List<string> { "English", "History" } }
};

// SelectMany flattens the nested collections
var allCourses = students.SelectMany(s => s.Courses);

// Result: "Math", "Science", "English", "History"

// SelectMany with student and course
var studentCourses = students.SelectMany(
    s => s.Courses,
    (student, course) => new { student.Name, course }
);

// Result:
// { Name = John, course = Math }
// { Name = John, course = Science }
// { Name = Jane, course = English }
// { Name = Jane, course = History }

// TypeScript Example with Advanced Types
interface ApiResponse<T> {
  data: T;
  status: number;
  message: string;
  timestamp: Date;
}

// Utility type for partial updates
type PartialUser = Partial<{
  id: number;
  name: string;
  email: string;
  role: 'admin' | 'user' | 'guest';
}>;

// Generic function with constraints
async function fetchApi<T>(
  endpoint: string,
  options?: RequestInit
): Promise<ApiResponse<T>> {
  const response = await fetch(endpoint, {
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
    ...options,
  });

  if (!response.ok) {
    throw new Error(`API error: ${response.status} ${response.statusText}`);
  }

  return response.json();
}

// Type guard function
function isSuccessResponse<T>(
  response: ApiResponse<T>
): response is ApiResponse<T> & { status: 200 } {
  return response.status === 200;
}
